import json, math
from pyscipopt import Model, quicksum
R=3960.0; START='depot_start'; END='depot_end'
def dist(a,b):
 la1,lo1=map(math.radians,(a['latitude'],a['longitude'])); la2,lo2=map(math.radians,(b['latitude'],b['longitude']))
 z=math.sin(la1)*math.sin(la2)+math.cos(la1)*math.cos(la2)*math.cos(lo2-lo1)
 return R*math.acos(max(-1,min(1,z)))
data=json.load(open('data.json')); ss=data['stations']; ids=[s['id'] for s in ss]; byid={s['id']:s for s in ss}; vs=range(1,data['vehicle_count']+1); C=data['vehicle_capacity']; M=3*C
coords={START:data['depot'],END:data['depot'],**byid}
arcs=[(START,i) for i in ids]+[(i,END) for i in ids]+[(i,j) for i in ids for j in ids if i!=j]
d={(i,j):dist(coords[i],coords[j]) for i,j in arcs}
m=Model('rebalance');m.hideOutput();m.setParam('limits/time',600.0);m.setParam('limits/gap',0.0)
x={(k,i,j):m.addVar(vtype='B') for k in vs for i,j in arcs}; v={(k,i):m.addVar(vtype='B') for k in vs for i in ids}
p={(k,i):m.addVar(vtype='I',lb=0,ub=C) for k in vs for i in ids}; q={(k,i):m.addVar(vtype='I',lb=0,ub=C) for k in vs for i in ids}; pos={(k,i):m.addVar(vtype='B') for k in vs for i in ids}; l={(k,i):m.addVar(vtype='I',lb=0,ub=C) for k in vs for i in ids}; sl={k:m.addVar(vtype='I',lb=0,ub=C) for k in vs}; el={k:m.addVar(vtype='I',lb=0,ub=C) for k in vs}; o={(k,i):m.addVar(lb=1,ub=len(ids)) for k in vs for i in ids}; u={i:m.addVar(vtype='I',lb=0) for i in ids}
for k in vs:
 m.addCons(quicksum(x[k,START,i] for i in ids)==1);m.addCons(quicksum(x[k,i,END] for i in ids)==1)
 for i in ids:
  inc=x[k,START,i]+quicksum(x[k,j,i] for j in ids if j!=i);out=x[k,i,END]+quicksum(x[k,i,j] for j in ids if j!=i)
  m.addCons(inc==v[k,i]);m.addCons(out==v[k,i]);m.addCons(p[k,i]<=C*pos[k,i]);m.addCons(q[k,i]<=C*(v[k,i]-pos[k,i]))
  op=p[k,i]-q[k,i]
  m.addCons(l[k,i]-sl[k]-op<=M*(1-x[k,START,i]));m.addCons(l[k,i]-sl[k]-op>=-M*(1-x[k,START,i]))
  m.addCons(el[k]-l[k,i]<=M*(1-x[k,i,END]));m.addCons(el[k]-l[k,i]>=-M*(1-x[k,i,END]))
  for j in ids:
   if i!=j:
    m.addCons(o[k,i]-o[k,j]+len(ids)*x[k,i,j]<=len(ids)-1)
    nop=p[k,j]-q[k,j]
    m.addCons(l[k,j]-l[k,i]-nop<=M*(1-x[k,i,j]));m.addCons(l[k,j]-l[k,i]-nop>=-M*(1-x[k,i,j]))
for s in ss:
 i=s['id']; net=quicksum(p[k,i]-q[k,i] for k in vs)
 m.addCons(s['initial_bikes']-net>=0);m.addCons(s['initial_bikes']-net<=s['station_capacity']);m.addCons(net-s['net_rebalancing_target']<=u[i]);m.addCons(s['net_rebalancing_target']-net<=u[i])
m.setObjective(quicksum(d[i,j]*x[k,i,j] for k in vs for i,j in arcs)+data['penalty_weight']*quicksum(u.values()),'minimize');m.optimize()
if not m.getNSols():raise RuntimeError(m.getStatus())
def iv(z):return int(round(m.getVal(z)))
veh=[]
for k in vs:
 succ={i:j for i,j in arcs if m.getVal(x[k,i,j])>.5};route=[START];stops=[];cur=START
 while cur!=END:
  cur=succ[cur];route.append(cur)
  if cur!=END:stops.append({'station_id':cur,'bikes_picked_up':float(iv(p[k,cur])),'bikes_dropped_off':float(iv(q[k,cur])),'load_after_stop':float(iv(l[k,cur]))})
 veh.append({'vehicle_id':k,'start_load':float(iv(sl[k])),'route':route,'stops':stops,'end_load':float(iv(el[k])})
st=[]
for s in ss:
 i=s['id']; pp=sum(iv(p[k,i]) for k in vs);qq=sum(iv(q[k,i]) for k in vs);net=pp-qq
 st.append({'station_id':i,'net_rebalancing_target':float(s['net_rebalancing_target']),'total_bikes_picked_up':float(pp),'total_bikes_dropped_off':float(qq),'net_bike_change':float(net),'unmet_rebalancing_amount':float(abs(s['net_rebalancing_target']-net))})
t=sum(d[i,j] for k in vs for i,j in arcs if m.getVal(x[k,i,j])>.5);um=sum(s['unmet_rebalancing_amount'] for s in st);pen=data['penalty_weight']*um
report={'summary':{'objective':t+pen,'travel_distance_miles':t,'unmet_rebalancing_penalty':pen,'total_unmet_rebalancing_amount':um},'vehicles':veh,'stations':st}
json.dump(report,open('report.json','w'),indent=2);open('report.json','a').write('\n');print(json.dumps(report,indent=2))
